#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, FAC;
    cin >> n >> FAC;

    const ll original = n;
    vector<ll> factors;

    for (ll i = 2; i <= n / i; ++i) {
        while (n % i == 0) {
            factors.push_back(i);
            n /= i;
        }
    }
    if (n > 1) factors.push_back(n);

    if (static_cast<ll>(factors.size()) < FAC) {
        cout << -1 << '\n';
        return 0;
    }

    ll product = 1;
    for (ll i = 0; i < FAC - 1; ++i) {
        cout << factors[i] << ' ';
        product *= factors[i];
    }
    cout << original / product << '\n';

    return 0;
}

